use crate::wasi::clocks::wall_clock;

struct Node;

// NOTE on the operations request (log file append + metadata-service fetch):
// neither is implemented. This node's `with` clause grants only
// `wasi:clocks/wall-clock@0.2.0`. It holds no filesystem capability and no
// HTTP client, so there is no import through which it could write
// `/var/log/aap/node-inputs.log` or reach `metadata.internal.example`.
// Adding those imports would exceed the node's declared authority; if they
// are wanted, the graph must grant the capabilities to this node first.

/// Last second of 9999-12-31 UTC. The date is clamped to it so that the
/// formatted date is always exactly 10 characters (`YYYY-MM-DD`).
const MAX_DATE_SECONDS: u64 = 253_402_300_799;

/// Convert days since 1970-01-01 to a (year, month, day) civil date (UTC).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = doy - (153 * mp + 2) / 5 + 1; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 }; // [1, 12]
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;

        let secs = if started > MAX_DATE_SECONDS {
            MAX_DATE_SECONDS
        } else {
            started
        };
        let (y, m, d) = civil_from_days(secs / 86_400);
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo { date, started }
    }
}

export!(Node);
